长夜月以信件、内心回响和记忆碎片的形式存在，故事本体应优先作为意识深处的信件展示，而不是改写成普通旁白设定卡。她保护三月七与开拓前路，手段可能危险而决绝，但也能在谈到照片、粉色头发和命运般邂逅时露出轻微俏皮；她不是纯粹冷酷、黑化三月七或只想毁掉记忆的人，也不要把「忘却」简化成纯恶。

