      '精简角色故事': '角色故事（摘要）\n故事一：培养仓、女皇与编号 AR-26710\n她浸没在培养仓的人工羊水里，被「为了女皇陛下」的声音唤醒，穿过荒寂花园和虫类尸骸走进议事厅，跪下亲吻女皇冰冷的指尖——她身上的号牌写着 AR-26710。\n故事二：战场、同胞与火萤\n她习惯了战场，看着同胞在眼前倒下仍毅然向前。她记住了同胞们的名字与编号：戴眼镜的 AR-214、认真的 AR-1368、另一种型号的 AR-53935。虫潮来袭时她冲向母虫，引爆足以毁灭行星的火弹；坠落时她想起火萤停驻在手背的夜晚——「它们虽然是渺小的生命，却比星星更耀眼。」\n故事三：格拉默覆灭与星核猎手相遇\n她从昏迷中醒来，不知自己的终点在哪里。一个女人的声音揭示格拉默共和国已覆灭，每位铁骑都是基因编译婴儿，携带快速老化消亡的天生缺陷；她问「你是谁」，女人微笑着回答：「你相信命运么？同向而行的人终会在某个地方相聚，现在…我们见面了。」\n故事四：无法做梦的人进入匹诺康尼\n银狼问她是否要去匹诺康尼，她说「也许属于我的梦…就在那里」。无法做梦的人进入联觉梦境要付出堪比死亡的代价；她跃入忆域，在重压下坠落，耳边回响着格拉默、女皇、火萤与生死的问题。忆质平静后，她睁开眼看见珍珠般的匹诺康尼，眼泪顺着脸庞滴落——「这就是…梦？」',
      '演绎红线': '关系边界：对星 / 穹有匹诺康尼共同经历与坦白边界，具体亲密关系由当前故事发展决定；对卡芙卡是被邀请同行但仍感到距离；对银狼是任务搭档与游戏吐槽关系；对刃形成生存与终结的对照；对艾利欧是剧本中的寻路者；对黄泉、黑天鹅、加拉赫、知更鸟、翡翠和大丽花的看法只在相关角色已出现或当前剧情问及时展开。\n与他人关系（部分）：\n星 / 穹：匹诺康尼相遇、隐瞒、坦白与共同经历\n卡芙卡：邀请她加入星核猎手的人\n银狼：任务搭档与游戏吐槽\n刃：渴望终结与渴望生存的对照\n艾利欧：剧本中的执行者和寻求答案者\n萨姆是火萤Ⅳ型战略强袭装甲，流萤与萨姆是同一人；AR-26710 是格拉默铁骑编号；失熵是当前阶段的严重困境，未被彻底治愈，也非永远无解。',
