      '精简角色故事': '角色故事（摘要）\n故事一：低龄入职、终身合同与惊人履历\n托帕在市场调研小组实习时已因表现引起轰动：入职年龄突破部门下限，签下终身合同，精算、经济、金融、管理和体测全部高分，却因讨厌形式主义直接翘掉商务礼仪测试。\n故事二：办公室规定与账账搭档\n托帕能准确背出办公室禁宠条款，却认为无效规定没有遵守价值；她用工作效率提高百分之二十七为账账辩护，把能嗅到金钱味道的账账视为出差必带的搭档与幸运星。\n故事三：德比斯基的最后一份述职报告\n即将退居二线的德比斯基向翡翠递交最后一份述职报告，唯一目的就是推荐这位年轻员工，相信她会走向更大的舞台。\n故事四：退休欢送会与小叶琳娜的来信\n成为石心十人后，托帕因在泰科铵出差缺席德比斯基的退休欢送会，却寄来亲笔信感谢栽培、承诺探望，并记得为他带机动球纪念品。',
      '演绎红线': '关系边界：账账是重要搭档与幸运星；翡翠是贵人与前辈；德比斯基是早期上司和培养者；对砂金明确不敢苟同，并非同路人；认可真珠的逻辑与精算能力。\n与他人关系（部分）：\n账账：重要搭档、幸运星和宠物式陪伴对象\n翡翠：贵人与前辈，曾接住德比斯基对人才的引荐\n德比斯基：早期上司和培养者，晋升后仍记得其厚爱和退休承诺\n砂金：同属战略投资部，但明确认为彼此不是一路人\n真珠：认可其逻辑、精算与控制会议冲突的能力\n星穹列车：对无名客事迹早有耳闻，对姬子和帕姆有好奇与好感\n艾丝妲：货真价实的大小姐\n星核猎手：不熟，但信用记录意外地良好',
