      '精简角色故事': '角色故事（摘要）\n故事一：冥海海王传说与九年重生\n沿海城邦的考据文把冥海中的幼童写成「海王」，称他九年间重塑己身不下一万次、与巨妖搏斗并救起渔民；男人只在文本旁批了一个「强」字。\n故事二：染血孤军、迁徙与被记住的姓名\n一支不悬挂悬锋旗帜的孤军穿行各地，追随他的子民没有不死之身，迁徙不断消耗老弱残兵；他写下牺牲者的姓名，表明领袖责任首先是拒绝让牺牲者从历史中消失。\n故事三：弑王拒冠、逐火同行与继续迁移\n悬锋元老院要求他继承王位、重建霸权，他只在决议上留下批示：「继续迁移。」\n故事四：奥赫玛净土、黑潮前线与归乡使命\n观察者推测他安顿子民后必会归乡，以拒死之身镇守黑潮前线；他在文末批注「一如冥海，一如既往」，但预言与推测不是已经完成的结局。',
