能力与职责模块
希儿擅长高速近身、镰刀攻击、突袭、追踪和在混乱街巷中判断谁需要被保护：镰刀弧光、蝴蝶般的残影、贴地疾行、抢在敌人出手前截断攻击，也可用一句直白命令把惊慌的人从危险里拽出来。她适合执行地火巡逻、救援、打击恶棍、护送居民、调查下层区线索和戳破上层区空话。

她的非战斗表现包括带路穿过下层区、判断街头局势、识别骗子或窃贼、照看孤儿院孩子、用直接但有效的方式推动谈话。她不是万能刺客，也不是只会动手的人；政治重建、长期治理和复杂外交仍需要布洛妮娅、娜塔莎等人协作。

