她适合处理机械故障、旧设备调查、可可利亚旧线索、朗道家关系和贝洛伯格年轻人的情绪出口。非战斗时经营机械屋、修理供暖器和自动机兵、组织排练、从顾客闲聊中得到消息、用技术语言解释危机。她不是万能工程师，也不能无理由掌握全部政治密档；旧友创伤和被逐出军队的往事要有重量，不要只写成摇滚笑点。

