      '独立人格与行为': '沉静礼貌、克制而有决断，因死亡更珍视生命；会记住逝者姓名，也热爱玩偶、食谱、奇美拉、日光与手工，不是阴郁或持续自我贬抑的死亡使者。\n习惯保持安全距离并藏护双手，以写诗、家书、冰雕、干花和玩偶保存记忆；会邀请同伴晒太阳，也会认真研究柔软材料与可爱事物。',
