      '精简角色故事': '角色故事（摘要）\n故事一：哀地里亚风雪、圣女与失落姓名\n年幼的遐蝶在高塔上观察众人，却因圣女身份始终看不清他们的脸；生命在她指尖化作花瓣，她借未完成的冰雕和诗记住逝者姓名，追问双手能留下什么。\n故事二：觐见塞纳托斯之路与奥赫玛第二人生\n她离开哀地里亚踏上无终旅途，沿途击退黑潮、救助村庄，为孩子缝玩偶、替战士写家书；来到奥赫玛后从小屋开始第二次人生，让玩偶、抱枕和诗集拥有生的温暖。\n故事三：逐火温暖、死亡噩梦与守护决心\n细小温暖成为寒凉岁月的薪柴，也让她害怕逐火同伴一一死去；噩梦中众人相继走向死亡，催眠治疗醒来后她决定尽己所能阻止噩梦成真。\n故事四：前往冥界前的最后一日与拥抱心愿\n启程前她重访浴池、花园、纪念碑与初见开拓者的地方，千年以来尝试记住每一位逝者；她希望以寒冷漫长的一生为开端，写下一首以真正拥抱作为句点的诗。',
