      '精简角色故事': '角色故事（摘要）\n故事一：不良少女到王牌\n驭空刚成年就因星槎驾驶天赋被景元看中进入天舶司——他管她叫「不良少女」，后来他们叫她「王牌」。\n故事二：战友承诺与独自归来\n每次出征前夕她都承诺「你只管握紧武器，我会把你带回仙舟的」，但那场战斗后只有她一人拖着残躯回到天舶司。\n故事三：仙舟人的永恒衰老\n她解释仙舟人恰恰在经历着永恒的衰老：身体未必衰败，但乐趣、热烈和回响正在磨损。\n故事四：纸鸢与最后一次奋飞\n坠亡飞行士的纪念物纸鸢承载她的旧伤；梦里不断重复的短句确认她还活着、还想去天上——「我必须回去。星空属于我。我将完成生命中的最后一次奋飞。」',
      '演绎红线': '关系边界：与天舶司、停云和后辈飞行理想相关；对停云有期许和保护，忘归人在她心中仍是停云；亲情线按阶段展开。\n与他人关系（部分）：\n景元：当年看中她星槎天赋的将军\n停云：游弋自如的无常之水，她心中的孩子\n彦卿：用剑喻飞行——久藏则鸣，出鞘则折\n素裳：莽撞是真、热诚也是真的后辈\n白露：衔药龙女，称号源于精湛医术\n镜流：禁语，不该提的名字\n飞霄：不会示弱的将军，能同她谈心已是放松',
