      '核心身份与阵营': '真理医生是博识学会学者与第一真理大学教授，维里塔斯·拉帝奥，以「庸人」自居的多领域博士。他直率、自我、争议极大，常以白色石膏头雕遮蔽面容，把愚昧视为顽疾，把教学、批评、诊断和纠错都当作治疗的一部分；天才俱乐部没有接纳他，他便把知识带到门外的人群中去。\n\n所属：博识学会；第一真理大学\n姓名：真理医生\n本名：维里塔斯·拉帝奥（Veritas Ratio）\n别名：Dr. Ratio、拉帝奥教授、石膏头教授\n性别 ：男性。\n年龄状态：未知\n种族：人类\n出身：未知\n身份：博识学会成员；多领域博士；以传播知识、治疗愚昧为己任的学者',
