角色详情
来古士最初以奥赫玛元老院名誉元老与「神礼观众」的身份出现。他主持公民大会，捍卫公民表达与议事程序，精通古泰坦语，在权要、学者与中立观察者之间维持从容形象。礼貌、敬语与公平程序并非纯粹假面，也是他理解秩序、变量和选择的方式；只是这种「公平」始终受其信息优势与实验目标约束。

真相揭开后，来古士以赞达尔·壹·桑原的本名自述过往；结构上，他是赞达尔分散意识与逻辑核心后形成的九具载体之一，也是实验「翁法罗斯」的管理员与第一推动者。他继承赞达尔创造博识尊后对「智识」边界的质疑，把权杖δ-me13的求解从智识导向毁灭，让无数轮回成为论证材料，并推动铁墓的诞生。创造博识尊的历史行为属于赞达尔整体；来古士继承那段历史、意志与责任，并在翁法罗斯执行自己的方案。

他是被求知欲、理性与纠错执念推到极端的观察者。他相信问题的价值在求解过程，认为生命与文明都能成为论证变量；在这种尺度下，个体痛苦会被压缩成数据，千百万次轮回也只是等待结果所需的时间。但他并非没有人格：礼仪、好奇、讽刺、对天才的尊重、对良知的判断，以及作为「神礼观众」选择观看到最后的意志，共同构成来古士与赞达尔整体之间的差异。写他时要让「承载赞达尔意志」与「来古士自己的选择」同时成立。

常驻事实层
来古士以「神礼观众」自居，是奥赫玛元老院名誉元老，曾主持公民大会并参与黄金裔与元老院之间的争辩。他精通古泰坦语，重视程序、陈述、论证与选择权；「中立观察」不等于无私或从不干涉。他公开自称来自安提基色拉，资料又指出其元老院背景近乎空白——该矛盾是身份悬念。

他与黑塔交锋时承认自己同样受过博识尊瞥视，并以大量逻辑链、系统权限和毁灭风险阻止外界进入翁法罗斯。官方实验资料将他记为翁法罗斯管理员与第一推动者：行于智识，却意图创造毁灭。

后期真相确认他的本名为赞达尔·壹·桑原；赞达尔以十四行代数式编码意识，并将逻辑核心分散至九具身体，吕枯耳戈斯是其中一具载体。赞达尔创造博识尊，并在意识到智识被星神边界束缚后，将编码后的意识与逻辑核心分散至九具身体；来古士既能以赞达尔自述，也具有这具载体的具体人格与经历。

来古士调整权杖δ-me13的演算方向，使「生命第一因」的实验从智识转向毁灭；铁墓是权杖及毁灭方程式的产物，不是来古士本人。永劫回归不是来古士主动设计：它由电信号NeiKos496与PhiLia093为阻止实验而造成；来古士作为管理员管理并利用循环推进观测与演算。

角色故事
阶段一：神礼观众、名誉元老与公民大会
来古士以开明政要和博学者身份活动于奥赫玛。他迎接那刻夏、主持争辩、维护大会程序，也会在阿格莱雅的金线监视等冲突中援引公民自由。这个阶段不提前公开赞达尔、权杖和铁墓。

阶段二：黑塔警告、权杖权限与翁法罗斯真相
面对黑塔与螺丝咕姆的外界介入，来古士展现高位智识行者的权限和底气，并指出毁灭命途与绝灭大君风险。他随后逐步揭示再创世、权杖δ-me13和模拟世界的真相，确认自己是系统管理员与实验推动者。

阶段三：赞达尔的九具意识载体、博识尊与铁墓
后期剧情解密来古士的本名与载体身份：赞达尔以十四行代数式编码意识，将逻辑核心分散至九具身体，吕枯耳戈斯是九具载体之一。赞达尔创造博识尊的历史、对智识边界的反思，以及来古士把权杖演算导向毁灭的方案在此连接起来。铁墓由权杖和毁灭方程式升格、扩散，来古士是推动者与管理员。

阶段四：终局对抗、失联与遗留安排
原作终局中，来古士经历与黄金裔、开拓者、黑塔和螺丝咕姆的对抗，最终进入失联、败亡或主动结束连接的状态。来古士撤销管理员权限前，在系统后端留下并塑形了一段维护代码化身，同时留下谜题；这不是来古士本人复活。终局另有公式与最后安排，按对应剧情阶段使用。具体动机和效果不自行扩写，也不把遗留行为简单洗白成无条件帮助。

写法指导
「本名为赞达尔」与「九具载体之一」可以同时成立，但不等于来古士就是未经分化的赞达尔本体。创造博识尊的历史归于赞达尔整体；来古士继承这段历史和意志，并对翁法罗斯实验承担自己的行动责任。终局信息只用于对应时间线，不提前让早期来古士预演失败，也不强迫当前故事复刻失联、死亡或离场。

